import{_ as p,l as t,o as e,c,v as r,p as i,x as s,d as l,i as d,S as n}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"kdump 与 crash","description":"","frontmatter":{"title":"kdump 与 crash","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kdump-crash.md","filePath":"cs/kdump-crash.md","lastUpdated":1789023840000}'),h={name:"cs/kdump-crash.md"};function m(u,a,k,_,f,x){const o=t("Mermaid");return e(),c("div",null,[a[1]||(a[1]=r('<h1 id="kdump-与-crash" tabindex="-1">kdump 与 crash <a class="header-anchor" href="#kdump-与-crash" aria-label="Permalink to &quot;kdump 与 crash&quot;">​</a></h1><div class="epigraph"><p>kdump 用 kexec 进第二内核，把崩溃瞬间的内存当 ram 盘转出；crash 工具在事后解析 vmcore。</p><footer>—— 据 Linux kdump 文档；kexec；[printk](/cs/printk-logging) 环可能不够事后分析</footer></div><p><a href="/cs/ebpf-observability">eBPF</a> 看活体。机器已经 oops。缺口是 <strong>保留内存 + 第二内核</strong> 抓 dump。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>崩溃时锁可能死、文件系统可能不可信。kexec 跳到预留的 capture kernel，旧内存只读。缺口：预留大小；加密盘；与 [watchdog]。本课不把 crash 命令当教程全文。</p><p><span class="marginnote">pstore/ramoops 是更小的紧急日志。对象是整机内存镜像，不是 coredump 用户进程——那是另一条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动预留 crashkernel → panic 时 kexec → 写 vmcore。对照 <a href="/cs/suspend-resume">hibernate</a>：一个有意写镜像，一个意外。对照 <a href="/cs/fsck">fsck</a>：dump 后再修盘。对照 makedumpfile 过滤页。</p>',8)),(e(),i(n,null,{default:s(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAN%5B%22panic%22%5D%20--%3E%20KX%5B%22kexec%20%E6%8D%95%E8%8E%B7%E5%86%85%E6%A0%B8%22%5D%0A%20%20KX%20--%3E%20VM%5B%22%E5%86%99%20vmcore%22%5D%0A%20%20VM%20--%3E%20CR%5B%22crash%20%E8%A7%A3%E6%9E%90%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>kdump 把「死内核的 RAM」变成可分析文件，是生产根因的最后手段。它需要事先预留，不能崩溃后再装。不要写成云监控套餐。与 <a href="/cs/kpti-os">KPTI</a>：解析要懂页表。</p><p>失败：预留不够、设备驱动在第二内核缺失。</p><p>实现上：crashkernel= 预留必须在启动时做，崩溃后再留来不及。第二内核驱动要能写盘或网，常用精简 config。过滤掉缓存页可缩小 dump。 读法上只引用<a href="/cs/ebpf-observability">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>kdump 与 crash</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有过滤策略。不保证虚拟机的 pvpanic 路径。下一课崩溃语义：oops 与 panic。</p><p>版本字段会变，课序钉的是机制对象「kdump 与 crash」，不是某一主线内核的结构体名。 后课默认：可 kexec 出 vmcore。oops 与 panic 如何决定活还是死，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>kdump：预留内核 + kexec + vmcore。</li><li>分析用 crash；依赖事先配置。</li><li>oops/panic 是下一课。</li><li>出处：kdump；kexec；crash 工具。</li></ul>',11))])}const E=p(h,[["render",m]]);export{T as __pageData,E as default};
